func newVersionsCmd(g *GlobalFlags) *cobra.Command {
	var knownModulesFile string
	c := &cobra.Command{
		Use:           "versions <module>",
		Short:         "List published versions of a Crow module",
		Args:          cobra.ExactArgs(1),
		SilenceUsage:  true,
		SilenceErrors: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			id, err := parseModuleAddress(args[0])
			if err != nil {
				return err
			}
			cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
			versions, err := cli.ListVersions(cmd.Context(), id)
			if err != nil {
				return err
			}
			for _, v := range versions {
				fmt.Fprintln(cmd.OutOrStdout(), v)
			}
			return nil
		},
	}
	c.Flags().StringVar(&knownModulesFile, "known-modules-file", "", "override known-modules autocomplete file (mostly for tests)")
	_ = c.Flags().MarkHidden("known-modules-file")
	c.ValidArgsFunction = func(_ *cobra.Command, args []string, _ string) ([]string, cobra.ShellCompDirective) {
		if len(args) > 0 {
			return nil, cobra.ShellCompDirectiveNoFileComp
		}
