68	// resolveKnownPath returns override if non-empty, otherwise the default
69	// known.Path(). Errors fall back to "" so Load and Add become no-ops.
70	func resolveKnownPath(override string) string {
71		if override != "" {
72			return override
73		}
74		p, err := known.Path()
75		if err != nil {
76			return ""
77		}
78		return p
79	}
80	
81	func newHTTPClient(d time.Duration) *http.Client {
82		return &http.Client{Timeout: d}
83	}
84	
85	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
86		parts := strings.Split(s, "/")
87		if len(parts) != 3 {
88			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
89		}
90		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
91		if err := id.Validate(); err != nil {
92			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
93		}
94		return id, nil
95	}
96	
97	func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
98		if len(args) == 0 {
99			return runInteractive(ctx, cmd, g, o)
100		}
101		if len(args) != 3 {
102			return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
103		}
104		id, err := parseModuleAddress(args[0])
105		if err != nil {
106			return err
107		}
108		if err := api.ValidateVersion(args[1]); err != nil {
109			return fmt.Errorf("%w: %v", ErrUsage, err)
110		}
111		if err := api.ValidateVersion(args[2]); err != nil {
112			return fmt.Errorf("%w: %v", ErrUsage, err)
113		}
114		modA := api.Module{ModuleIdentifier: id, Version: args[1]}
115		modB := api.Module{ModuleIdentifier: id, Version: args[2]}
116	
117		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
118		cache, err := registry.NewDiskCache(o.CacheDir)
119		if err != nil {
120			return fmt.Errorf("cache init: %w", err)
121		}
122		reg := registry.New(cli, cache)
123	
124		aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
125		if err != nil {
126			return err
127		}
128	
129		modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
130		if err != nil {
131			return fmt.Errorf("%w: %v", ErrArchive, err)
132		}
133		modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
134		if err != nil {
135			return fmt.Errorf("%w: %v", ErrArchive, err)
136		}
137	
138		result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
139		if o.Semantic {
140			sem, err := diff.Semantic(modAExtracted, modBExtracted)
141			if err != nil {
142				return fmt.Errorf("%w: %v", ErrSemantic, err)
143			}
144			result.Semantic = sem
145		}
146	
147		if err := known.Add(resolveKnownPath(o.KnownModulesFile),
148			id.Namespace+"/"+id.Name+"/"+id.Provider); err != nil {
149			_ = err // best-effort: cache failure does not block diff
150		}
151	
152		if g.JSON {
153			return renderJSON(cmd.OutOrStdout(), result)
154		}
155		if !o.Plain && isTTY(cmd.OutOrStdout()) {
156			return tui.RunBrowser(ctx, result)
157		}
158		return renderPlain(cmd.OutOrStdout(), result)
159	}
