161	// isTTY reports whether w is a *os.File backed by a terminal.
162	func isTTY(w io.Writer) bool {
163		f, ok := w.(*os.File)
164		if !ok {
165			return false
166		}
167		return term.IsTerminal(int(f.Fd()))
168	}
169	
170	func runInteractive(ctx context.Context, cmd *cobra.Command, g *GlobalFlags, o *diffOpts) error {
171		if !isTTY(cmd.OutOrStdout()) {
172			return fmt.Errorf("%w: interactive mode requires a TTY", ErrUsage)
173		}
174		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
175		cache, err := registry.NewDiskCache(o.CacheDir)
176		if err != nil {
177			return fmt.Errorf("cache init: %w", err)
178		}
179		reg := registry.New(cli, cache)
180	
181		// Stage 1: picker → fetched bytes
182		p := tui.NewPicker(ctx, &tui.Deps{Client: cli, Reg: reg})
183		prog := tea.NewProgram(p, tea.WithAltScreen(), tea.WithContext(ctx))
184		if _, err := prog.Run(); err != nil {
185			return err
186		}
187		aBytes, bBytes := p.Bytes()
188		if aBytes == nil || bBytes == nil {
189			// User quit before completing picker; not an error.
190			return nil
191		}
192	
193		// Stage 2: extract + diff + browser
194		modA, err := archive.Extract(aBytes, maxArchiveBytes)
195		if err != nil {
196			return fmt.Errorf("%w: %v", ErrArchive, err)
197		}
198		modB, err := archive.Extract(bBytes, maxArchiveBytes)
199		if err != nil {
200			return fmt.Errorf("%w: %v", ErrArchive, err)
201		}
202		result := diff.Result{Files: diff.Textual(modA, modB)}
203		if o.Semantic {
204			sem, err := diff.Semantic(modA, modB)
205			if err != nil {
206				return fmt.Errorf("%w: %v", ErrSemantic, err)
207			}
208			result.Semantic = sem
209		}
210		return tui.RunBrowser(ctx, result)
211	}
212	
213	// renderPlain writes the diff result to w in unified-diff format.
214	// "no differences" is emitted when there are zero files in the result.
215	func renderPlain(w io.Writer, r diff.Result) error {
216		if len(r.Files) == 0 && len(r.Semantic) == 0 {
217			_, err := fmt.Fprintln(w, "no differences")
218			return err
219		}
220		for i, fd := range r.Files {
221			if i > 0 {
222				_, _ = fmt.Fprintln(w)
223			}
224			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
225			_, _ = fmt.Fprint(w, fd.Unified)
226		}
227		if len(r.Semantic) > 0 {
228			_, _ = fmt.Fprintln(w)
229			_, _ = fmt.Fprintln(w, "=== semantic changes ===")
230			for _, c := range r.Semantic {
231				_, _ = fmt.Fprintf(w, "%s %s %s\n", c.Status, c.Kind, c.Name)
232			}
233		}
234		return nil
235	}
236	
237	func renderJSON(w io.Writer, r diff.Result) error {
238		type fileOut struct {
239			Path    string `json:"path"`
240			Status  string `json:"status"`
241			Adds    int    `json:"adds"`
242			Dels    int    `json:"dels"`
243			Unified string `json:"unified"`
244		}
245		type semOut struct {
246			Kind   string `json:"kind"`
247			Name   string `json:"name"`
248			Status string `json:"status"`
249			Detail string `json:"detail,omitempty"`
250		}
251		type payload struct {
252			Files    []fileOut `json:"files"`
253			Semantic []semOut  `json:"semantic,omitempty"`
254		}
255		out := payload{Files: make([]fileOut, 0, len(r.Files))}
256		for _, fd := range r.Files {
257			out.Files = append(out.Files, fileOut{Path: fd.Path, Status: fd.Status.String(), Adds: fd.Adds, Dels: fd.Dels, Unified: fd.Unified})
258		}
259		for _, c := range r.Semantic {
260			out.Semantic = append(out.Semantic, semOut{Kind: c.Kind, Name: c.Name, Status: c.Status.String(), Detail: c.Detail})
261		}
262		return json.NewEncoder(w).Encode(out)
263	}
